INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-04' FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Real-time CAE clearance, universal since 2019 -- one of the world''s longest-running e-invoicing mandates, still actively evolving', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Argentina''s e-invoicing rules change through frequent ARCA general resolutions; confirm current requirements directly with ARCA or a local tax advisor before relying on this page for compliance decisions.', 'Argentina pioneered electronic invoicing in the region, moving from a voluntary system (2003) to a mandatory one for VAT-registered and VAT-exempt taxpayers under RG 3749/2015, then to an effectively universal mandate covering every monotributista and final-consumer sale from 1 April 2019 (RG 4290/2018). Rather than settling once universal, the system has kept receiving substantive updates: a 2024 rebrand from AFIP to ARCA, an updated technical specification with itemized VAT and FX disclosure in 2025 (RG 5616/2024), a pre-filled VAT-return system in November 2025 (RG 5705/2025, "IVA Simple"), and a further sector expansion plus consolidated monthly invoicing option effective 1 July 2026 (RG 5824/2026).', 'Argentina uses its own domestic XML schema rather than UBL or EN 16931 -- every invoice is authorized in real time and stamped with a CAE (Código de Autorización Electrónico) before it can reach the buyer, with a QR code mandatory on every printed or PDF copy since 2021.', 'Coverage is about as broad as this tracker has seen anywhere: B2B, B2G, B2C, and exports are all in scope, for every VAT-registered taxpayer, every monotributista, and (from 1 July 2026) additional sectors including financial entities, insurers, credit-card administrators, prepaid health plans, and educational institutions. Foreign entities registered in Argentina face the same obligations as domestic taxpayers.', 'Because the mandate is already universal, most of the real work for a business already operating in Argentina is staying current with ARCA''s frequent technical updates -- rather than working out whether the mandate applies at all, which it almost certainly does.', 'Argentina backs its e-invoicing mandate with a real enforcement mechanism: temporary closure of the business premises for failing to issue a compliant invoice, and rejection of the buyer''s VAT credit if the invoice they hold lacks a valid CAE.', 'Argentina''s e-invoicing regime began as a voluntary system in 2003 and became mandatory for VAT-registered and VAT-exempt taxpayers under General Resolution 3749/2015. General Resolution 4290/2018 completed the rollout: from 1 April 2019, every monotributista had to issue electronic invoices, including sales to final consumers, making the mandate effectively universal. The system runs on real-time clearance -- ARCA (renamed from AFIP in 2024) validates each invoice''s XML and assigns a CAE before delivery to the buyer, an invoice lacking a valid CAE having no fiscal validity for either party. The mandate has kept evolving since going universal: RG 5616/2024 (effective 15 April 2025) mandated updated web services and itemized VAT/FX disclosure; RG 5705/2025 introduced pre-filled VAT returns built from e-invoice data; and RG 5824/2026 (effective 1 July 2026) extended the mandate to further sectors and introduced a consolidated monthly invoicing option for high-volume issuers. Non-compliance carries a real closure penalty of two to six days under Ley 11.683, Article 40.', '🇦🇷' FROM countries WHERE name_en = 'Argentina';
