INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2-6 days', 'Closure penalty for non-issuance (Ley 11.683, Art. 40)');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Format", "XML per ARCA''s own domestic schema -- not UBL or EN 16931"], ["Digital signature", "Not required on the invoice itself; the CAE is ARCA''s own real-time validation"], ["QR code", "Mandatory on every printed or PDF invoice since 2021, encoding the CAE and invoice data"], ["Invoice types", "A (registered buyer), B (final consumer), C (monotributista), E (export), plus credit/debit notes"]]', 'Argentina built its own format well before EN 16931 existed, so a domestic invoice looks nothing like a European UBL document -- exporters dealing with EU buyers need to handle both worlds separately.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer ID", "CUIT (Clave Única de Identificación Tributaria)"], ["Registration", "Digital tax certificate with ARCA, used to request CAE authorization"], ["Governing body", "ARCA -- Agencia de Recaudación y Control Aduanero (renamed from AFIP in 2024)"], ["Issuance channels", "The ''Comprobantes en Línea'' web portal, the mobile app, or a certified web-service integration"]]', 'The 2024 AFIP-to-ARCA rebrand was organizational, not technical -- the CUIT, the CAE process, and the underlying web services all carried over unchanged.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Core fields", "Issuer/buyer CUIT, invoice type, date, line items, VAT breakdown"], ["Since RG 5616/2024", "VAT itemized by rate, and the FX rate disclosed on foreign-currency invoices"], ["Retention", "10 years, in the original XML, by both issuer and buyer -- domestic storage required by default"]]', 'The 2025 itemization requirement is a real, current compliance gap for older integrations still submitting a single VAT total rather than a per-rate breakdown.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Invoicing model", "Real-time clearance -- ARCA validates and issues a CAE before the invoice reaches the buyer"], ["Coverage", "B2B, B2G, B2C, and exports -- effectively universal since 1 April 2019"], ["Transmission", "Certified web service (H2H), the ''Comprobantes en Línea'' portal, or the mobile app"], ["Without a valid CAE", "The invoice has no fiscal validity for either the issuer or the buyer"]]', 'This is a genuine clearance model, not a post-audit reporting one -- the invoice legally does not exist as a tax document until ARCA has already approved it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory today', '[["VAT-registered taxpayers", "Mandatory since 2015 (RG 3749/2015)"], ["Monotributistas & final-consumer sales", "Mandatory since 1 April 2019 (RG 4290/2018)"], ["Financial, insurance, prepaid-health & education sectors", "Newly in scope from 1 July 2026 (RG 5824/2026)"], ["Foreign entities registered in Argentina", "Same obligations as domestic taxpayers"]]', 'By 2019 there was, in practice, no remaining category of Argentine taxpayer issuing paper invoices -- the 2026 sector expansion adds specific entity types the earlier waves hadn''t explicitly named, rather than opening up a genuinely new gap.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Actively evolving, not a settled system', '[["2024", "AFIP renamed ARCA (Agencia de Recaudación y Control Aduanero)"], ["15 Apr 2025", "Updated web services, itemized VAT, and FX disclosure (RG 5616/2024)"], ["Nov 2025", "''IVA Simple'' -- pre-filled VAT returns built from e-invoice data (RG 5705/2025)"], ["1 Jul 2026", "New sectors added; consolidated monthly invoicing option introduced (RG 5824/2026)"]]', 'Few mandates this mature keep receiving genuine, dated updates at this pace -- treat Argentina as a system to monitor going forward, not a box to check once.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 A real closure penalty, not just a fine', NULL, NULL, 'Failing to issue a compliant invoice can trigger a temporary closure of the business premises -- two to six days under Ley 11.683, Article 40 -- doubling in severity if a repeat violation is detected within two years. This is a materially harder consequence than the fixed monetary fines most tracked countries use.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 No CAE, no deduction', NULL, NULL, 'An invoice lacking a valid CAE has no fiscal validity for either side of the transaction: the issuer has effectively not invoiced at all, and the buyer holding it cannot claim the related VAT credit or income-tax deduction. The clearance step is not a formality -- it''s the thing that makes the document usable for tax purposes at all.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌎 One of the region''s oldest systems -- still not standing still', NULL, NULL, 'Argentina has run some form of e-invoicing since 2003 and a fully universal mandate since 2019, making it one of the most mature systems this tracker covers. Rather than settling, it has picked up substantive changes in nearly every year since -- 2024''s ARCA rebrand, 2025''s technical and reporting updates, and 2026''s sector expansion -- worth watching the same way this tracker watches Turkey or South Korea.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice not issued, or issued without a valid CAE', '2-6 day closure of the business premises (Ley 11.683, Art. 40)', 'Doubles if repeated within 2 years');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Buyer holds an invoice lacking a valid CAE', 'VAT input-credit and income-tax deduction rejected', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your invoicing setup requests and stores a CAE for every invoice', 'An invoice without a valid CAE has no fiscal validity -- this is the single most important check for any business already invoicing in Argentina.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you''re a monotributista or sell to final consumers, confirm electronic Type B invoicing is fully in place', 'This has been mandatory since 1 April 2019 with no remaining paper option for standard categories.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Update to RG 5616/2024''s web-service specification if you haven''t already', 'Invoices must itemize VAT by rate and disclose the FX rate used on foreign-currency transactions -- a real gap for integrations still on the older schema.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you''re in financial services, insurance, prepaid health, or education, confirm onboarding for the 1 July 2026 sector expansion', 'RG 5824/2026 brought these sectors explicitly into scope alongside a new ARS 10 million consumer-identification threshold.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Argentina';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Evaluate the monthly consolidated settlement voucher for high-volume client billing', 'The ''liquidación electrónica mensual'' introduced by RG 5824/2026 lets qualifying issuers consolidate a client''s transactions into one monthly invoice rather than one per operation.');
